head.script:
scwin.gVar = {
    "cValidator" : "",
    "cValue" : "",
    "nValidatorCall" : 0,
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > M > validate]<br/>입력값에 대한 유효성 체크를 실행한 후 결과값을 반환합니다.",
    "validation" : [
        "validate() 메소드는 validator 속성에 설정된 사용자 정의 함수와 별개로 유효성 체크를 실행합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (자체 값 selectbox 는 value)
    con_validator.setValue("scwin.fn_validator");
    con_value.setValue("empty");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 mandatory=true, displaymessage=true 로 고정하고 validator 와 입력값은 위 조건에서 선택합니다\n[절차] 조건 선택 -> Target 재생성 -> validate 버튼 클릭 / validator 설정 시 target1 클릭 후 바깥 영역 클릭 (포커스 해제) 도 함께 수행\n[확인] validator 설정 여부와 관계없이 같은 입력값이면 validate() 반환값과 alert 표시가 같은지, validate() 실행 중 사용자 정의 함수 호출 횟수\n[참고] 사용자 정의 함수는 포커스 해제 시에만 실행되어 결과창에 실행 줄이 출력됩니다"', '', 'label1');

    // 조건 설정
    scwin.gVar["cValidator"] = con_validator.getValue();
    scwin.gVar["cValue"] = con_value.getValue();

    let properties = {
        mandatory : "true",
        displaymessage : "true",
        validator : scwin.gVar["cValidator"],
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList);

    // 헬퍼가 넣은 초기값 secret 을 선택한 입력값으로 덮음 (빈값 선택 시 mandatory 실패 케이스)
    if (scwin.gVar["cValue"] === "empty")
        target1.setValue("");
    else
        target1.setValue(scwin.gVar["cValue"]);
}



// validate 실행 - validation 1 판정 출력
scwin.btn_validate_onclick = function (e) {
    let strValue = target1.getValue() || "";

    // validate() 실행 중 사용자 정의 함수 호출 횟수만 집계 (버튼 클릭에 의한 포커스 해제 호출은 제외)
    scwin.gVar["nValidatorCall"] = 0;

    let rtn = target1.validate();

    let strValidator = (scwin.gVar["cValidator"] === "") ? "미설정" : scwin.gVar["cValidator"];

    wf_body_bottom.getObj("scwin").setReturnValue("validator " + strValidator + " / 입력값 " + strValue.length + "자 -> validate() 반환값 : " + rtn + " / validate() 실행 중 사용자 정의 함수 호출 : " + scwin.gVar["nValidatorCall"] + "회");
}



// validator 로 설정되는 사용자 정의 함수 (입력값을 그대로 반환) - validation 1 판정 출력
scwin.fn_validator = function (val, id) {
    scwin.gVar["nValidatorCall"]++;

    wf_body_bottom.getObj("scwin").setReturnValue("▶ validator 사용자 정의 함수 실행 (입력값 " + val.length + "자)");

    return val;
}
